"""Publish an indexable drone print collection after generate_cad_library.py."""
from pathlib import Path
from html import escape
import json
import zipfile
from drone_parts import PARTS

ROOT=Path(__file__).absolute().parent
BASE='https://chamanprakashkanth.github.io/Mechanical-Engineering-Market-Position-Dashboard/'
url=BASE+'engineering-careers/drone-cad-library.html'
css='''
:root{color-scheme:dark;--ink:#f0f6f8;--muted:#bed0d8;--mint:#a8ecd2;--line:#37525c}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top right,#164841,transparent 50%),#0b151c;color:var(--ink);font:17px/1.7 system-ui,sans-serif}header,main,footer{max-width:1160px;margin:auto;padding:24px}header,nav,.actions{display:flex;gap:18px;flex-wrap:wrap}header{justify-content:space-between;border-bottom:1px solid var(--line)}a{color:var(--mint);text-underline-offset:4px}.brand{font-weight:800;font-size:23px;text-decoration:none}.eyebrow{letter-spacing:.12em;color:var(--mint);font-size:12px;font-weight:800}h1{font-size:clamp(36px,5vw,62px);line-height:1.1;letter-spacing:-.04em}h2,h3{line-height:1.3}p,li{color:var(--muted)}.panel,.card{border:1px solid var(--line);border-radius:18px;padding:24px;background:#142831;margin:24px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.card{margin:0}.card img{width:100%;height:220px;object-fit:contain;background:#0b161b;border-radius:12px}.button{display:inline-block;padding:12px 18px;background:var(--mint);color:#082626;text-decoration:none;border-radius:9px;font-weight:750}.details{font-size:14px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid var(--line)}.table{overflow-x:auto}a:focus-visible{outline:3px solid white;outline-offset:4px}@media(max-width:700px){.grid{grid-template-columns:1fr}header,main,footer{padding:18px}}'''
cards=[]
items=[]
for i,p in enumerate(PARTS,1):
    page='cad-'+p['slug']+'.html'
    cards.append(f'<article class="card"><img loading="lazy" width="600" height="380" src="../assets/cad/{p["slug"]}.svg" alt="Original {escape(p["title"])} geometry preview"><h2><a href="{page}">{escape(p["title"])}</a></h2><p>{escape(p["dims"])}</p><p class="details">{escape(p["printing"])}</p><div class="actions"><a class="button" download href="../assets/cad/{p["slug"]}.stl">Download STL</a><a download href="../assets/cad/{p["slug"]}.scad">Editable OpenSCAD</a><a href="{page}">Dimensions &amp; print notes</a></div></article>')
    items.append({'@type':'ListItem','position':i,'name':p['title'],'url':BASE+'engineering-careers/'+page})
graph={'@context':'https://schema.org','@type':'CollectionPage','name':'Free Drone STL Files and Editable CAD Accessories','url':url,'description':'Six original 3D-printable drone accessory studies with STL, editable OpenSCAD, dimensions and print orientations.','mainEntity':{'@type':'ItemList','numberOfItems':len(PARTS),'itemListElement':items}}
description='Download six free drone STL accessories: GPS and receiver trays, capacitor cradle, antenna cable guide, arm wire cover and battery strap guide. Editable OpenSCAD included.'
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Free Drone STL Files: GPS, Antenna &amp; Cable Mounts | MechIntel</title><meta name="description" content="{escape(description,quote=True)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{url}"><meta property="og:title" content="Free Drone STL Files &amp; Editable CAD Accessories"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:type" content="website"><meta property="og:image" content="{BASE}assets/mechintel-social-cover.png"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">{json.dumps(graph)}</script><style>{css}</style></head><body><header><a class="brand" href="../">MechIntel</a><nav><a href="cad-library.html">All CAD parts</a><a href="shaft-spacer-generator.html">CAD Generator</a><a href="gate-mechanical-books.html">GATE Books</a></nav></header><main><p class="eyebrow">ORIGINAL DRONE ACCESSORIES · PRINTABLE MESHES + EDITABLE SOURCE</p><h1>Drone parts for 3D printing</h1><p>Download six original FPV and inspection-drone accessory studies. Start with an STL for slicing, or edit the OpenSCAD source for your measured module, arm or strap. Each page includes dimensions, retention notes and a suggested print orientation.</p><div class="actions"><a class="button" download href="../assets/cad/drone-cad-print-pack.zip">Download all six (.zip)</a><a href="../assets/cad/drone-print-notes.txt">Read the print notes</a></div><section class="panel"><h2>Which drone parts can I 3D print?</h2><p>Accessory trays, cable guides and covers are useful starting points for a printer. This collection provides nominal geometry for GPS modules, receiver boards, capacitors, antenna cables, arm wiring and battery webbing. These are original generic studies, not manufacturer replacement files or flight-qualified hardware.</p><p>The STL meshes were checked for closed edges, connected surfaces, positive volume and non-degenerate triangles. They have not been physically printed or flight-tested. Import in <strong>millimetres</strong>, check the slicer preview, and measure your hardware before use.</p></section><div class="grid">{''.join(cards)}</div><section class="panel"><h2>Choose the first part to print</h2><div class="table"><table><thead><tr><th>Your need</th><th>Starting model</th><th>Measure first</th></tr></thead><tbody><tr><td>Hold a square GPS module</td><td>25 mm GPS tray</td><td>Module outline, connectors, sky clearance</td></tr><tr><td>Route a pair of antenna cables</td><td>Dual cable guide</td><td>Sleeve diameter, bend radius, antenna active area</td></tr><tr><td>Support a capacitor with soft ties</td><td>Capacitor strap cradle</td><td>Body diameter, terminal and pressure-vent access</td></tr><tr><td>Hold a compact receiver board</td><td>20 × 12 mm receiver tray</td><td>Board, components, solder joints and insulation</td></tr><tr><td>Cover an arm wire bundle</td><td>14 mm wire-cover tunnel</td><td>Arm and wires together, propeller envelope</td></tr><tr><td>Route webbing</td><td>20 mm strap bridge</td><td>Actual strap width, seams and thickness</td></tr></tbody></table></div><h2>How do I customize a drone STL?</h2><p>For this collection, edit the named dimensions in the matching OpenSCAD file, render it, and export a new STL. Several mounting offsets are also explicit expressions in the source; review the entire geometry when changing dimensions. STL alone is a triangle mesh and does not preserve editable design parameters.</p><h2>Should I use TPU, PETG or PLA?</h2><p>TPU is a candidate for compliant cable guides and soft retention accessories; PETG can be evaluated for rigid tray fit trials. PLA can be used for a bench dimension check, but material choice for an installed part depends on heat, UV, creep, vibration, geometry and printing quality. Use the filament supplier profile rather than treating one temperature or infill setting as universal. The <a href="https://help.prusa3d.com/article/flexible-materials_2057">Prusa flexible-material guide</a> explains TPU printing considerations.</p><h2>Do these parts fit my drone?</h2><p>Match the published dimensions to your measured hardware. A module name or nominal board size does not establish component, connector or frame compatibility. Make a small fit coupon first, then check retention and clearances with power disconnected.</p><h2>Are these files free for commercial use?</h2><p>Yes. The original geometry is released under <a href="https://creativecommons.org/publicdomain/zero/1.0/">CC0 1.0</a>. No third-party STL or supplier drawing was copied. The release supplies geometry without warranty or certification.</p><h2>Application references</h2><p><a href="https://ardupilot.org/copter/docs/common-installing-3dr-ublox-gps-compass-module.html">ArduPilot GPS/compass mounting</a> describes sky view and separation from magnetic interference. <a href="https://www.expresslrs.org/hardware/hardware-selection/">ExpressLRS hardware guidance</a> discusses antenna choices and carbon obstruction. These sources explain installation context; they do not validate our model dimensions.</p><p>All mesh and source generation uses local CPU geometry. The website has no model-generation API, AI inference or GPU requirement.</p></section></main><footer>MechIntel · Original drone accessory studies · 16 October 2026 · STL + OpenSCAD · CC0</footer></body></html>'''
html=html.replace(BASE+'assets/mechintel-social-cover.png',BASE+'assets/cad/drone-print-preview.png')
html=html.replace('<div class="grid">','<img src="../assets/cad/drone-print-preview.png" width="1800" height="1080" alt="Six original drone accessories rendered from their generated mesh geometry" style="width:100%;height:auto;border-radius:18px"><div class="grid">',1)
(ROOT/'engineering-careers/drone-cad-library.html').write_text(html,encoding='utf-8')
notes='MechIntel drone print pack — original CC0 geometry — units mm\nSix accessories, 16 October 2026. No copied supplier CAD.\nClosed connected STL meshes checked computationally; no physical prints or flight testing.\nImport STL as millimetres. Keep installed parts clear of props, wiring and cooling.\nEdit named parameters and review all offsets in OpenSCAD, then render/export STL locally.\n\n'
for p in PARTS:notes+=p['title']+'\n'+p['dims']+'\n'+p['notes']+'\n\n'
out=ROOT/'assets/cad'
(out/'drone-print-notes.txt').write_text(notes.rstrip()+'\n',encoding='utf-8')
with zipfile.ZipFile(out/'drone-cad-print-pack.zip','w',zipfile.ZIP_DEFLATED) as z:
    z.write(out/'drone-print-notes.txt','README.txt')
    for p in PARTS:
        for ext in ['stl','scad','svg']:
            path=out/(p['slug']+'.'+ext);z.write(path,path.name)
print('Created drone print hub and six-part download pack.')
